<div class="container-fluid"><div class="card shadow"><div class="card-header"><h5 class="m-0">Aksi Direktur</h5></div><div class="card-body"><p><strong><?php echo html_escape($surat->no_surat); ?></strong><br><?php echo html_escape($surat->perihal); ?> | <?php echo html_escape($surat->tujuan); ?></p><?php if ($surat->file_ber_nomor): ?><a class="btn btn-sm btn-outline-primary mb-3" href="<?php echo site_url('surat/download/' . $surat->id . '/numbered'); ?>">Download dokumen bernomor</a><?php endif; ?><form method="post" enctype="multipart/form-data" action="<?php echo site_url('surat_direktur/simpan/' . $surat->id); ?>"><div class="form-group"><label>Aksi</label><select name="aksi" class="form-control" required><option value="ttd">Tanda Tangani</option><option value="disposisi">Disposisi</option></select></div><div class="form-group"><label>Tujuan disposisi</label><select name="ke_user" class="form-control"><option value="">Pilih user/bagian</option><?php foreach ($users as $user): ?><option value="<?php echo $user->id; ?>"><?php echo html_escape($user->name . ' - ' . $user->email); ?></option><?php endforeach; ?></select></div><div class="form-group"><label>Catatan / instruksi</label><textarea name="catatan" class="form-control" rows="3"></textarea></div><div class="form-group"><label>Dokumen hasil TTD (.pdf, .doc, .docx, .jpg, .png)</label><input type="file" name="file_final" class="form-control-file" accept=".pdf,.doc,.docx,.jpg,.jpeg,.png"></div><button class="btn btn-primary">Simpan Aksi</button></form></div></div></div>
